names={'ana':'Anatomy','phy':'Physiology','bio':'Biochemistry','pat':'Pathology','pha':'Pharmacology'}
out=[];tot=0
for k,Q in S.items():
    for n,(p,o,a,e) in enumerate(Q,1):
        assert len(o)==4 and 0<=a<4 and '`' not in p+e+''.join(o),(k,n)
        rt=o[a];tgt=(n*3+len(k)+ord(k[0]))%4
        others=[x for i,x in enumerate(o) if i!=a];random.Random(k+str(n)).shuffle(others);others.insert(tgt,rt)
        out.append("{id:`q-fcps-%s2-%02d`,type:`multiple-choice`,topic:`fcps`,difficulty:`advanced`,prompt:`%s`,options:J(%s),correctOptionId:`%s`,explanation:`%s`,learningObjective:`FCPS Part I: %s`,relatedStructureIds:[],sources:[]}"%(k,n,p,",".join("`%s`"%x for x in others),'abcd'[tgt],e,names[k]))
    tot+=len(Q);print(k,len(Q))
open('ang/vig.js','w').write(",".join(out)+",");print(tot)
